window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-25201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῖκνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 594 na letra λ · nº geral 25201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cesta 2 berço de vime 3 joeira 4 joeira para o trigo 5 joeira sagrada das primícias.</p></section></article>\n<article id=\"entry-dgp-25202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικνοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 595 na letra λ · nº geral 25202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que leva a joeira sagrada nas festas de Dioniso. 〈λῖκνον, φέρω〉</p></section></article>\n<article id=\"entry-dgp-25203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικριφίς</h1><div class=\"entry-meta\"><span>DGP · ordem 596 na letra λ · nº geral 25203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de lado; obliquamente.</p></section></article>\n<article id=\"entry-dgp-25204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λικύμνιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 597 na letra λ · nº geral 25204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Licímnio, n. de h.</p></section></article>\n<article id=\"entry-dgp-25205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιλαίομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 598 na letra λ · nº geral 25205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf., perf. λελίημαι, m.-q.-perf. 3ª sing. λελίητο) ép. desejar ardentemente; esforçar-se; ansiar por, gen., ou para, inf.: λιλ. πολέμοιο hom. desejar o combate, λιλαίομαι πολεμίζειν hom. desejar combater, λιλαιομένη χροὸς ἆσαι hom. [dardo] ansioso por saciar-se de carne, φόωσδε λιλαίεο hom. anseia por retornar à luz do dia.</p></section></article>\n<article id=\"entry-dgp-25206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 599 na letra λ · nº geral 25206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sentir fome. 〈λιμός〉</p></section></article>\n<article id=\"entry-dgp-25207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμήν, ένος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 600 na letra λ · nº geral 25207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 porto: λιμένες θαλάσσης hom. portos para proteger-se do mar, λ. χείματος eur. porto para proteger-se da tempestade 2 lugar para abrigar-se; abrigo; refúgio: λ. ἑταιρίας sóf. abrigo da amizade, λ. κακῶν ésql. refúgio contra os males, λιμὴν πέφανται τῶν ἐμῶν βουλευμάτων eur. apareceu como um porto para meus planos 3 depósito: λ. πλούτου ésql. depósito de tesouros 4 sede; morada: λ. παντὸς οἰωνοῦ sóf. morada de pássaros de toda espécie.</p></section></article>\n<article id=\"entry-dgp-25208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 601 na letra λ · nº geral 25208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 faminto; pobre; miserável 2 ávido. 〈λιμός〉</p></section></article>\n<article id=\"entry-dgp-25209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίμνα</h1><div class=\"entry-meta\"><span>DGP · ordem 602 na letra λ · nº geral 25209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = λίμνη.</p></section></article>\n<article id=\"entry-dgp-25210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμνάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 603 na letra λ · nº geral 25210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intr. (região) ser ou tornar-se pantanoso 2 intr. (água) ser ou tornar-se estagnado 3 transformar em pântano; inundar. 〈λίμνη〉</p></section></article>\n<article id=\"entry-dgp-25211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίμναι, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 604 na letra λ · nº geral 25211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os Pântanos, bairro de Atenas.</p></section></article>\n<article id=\"entry-dgp-25212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 605 na letra λ · nº geral 25212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se encontra no pântano 2 que vive nas lagoas ou nos pântanos 3 próprio para lagoa ou pântano (barco). 〈λίμνη〉</p></section></article>\n<article id=\"entry-dgp-25213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμνάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 606 na letra λ · nº geral 25213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de pântano; de lagoa. 〈λίμνη〉</p></section></article>\n<article id=\"entry-dgp-25214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίμνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 607 na letra λ · nº geral 25214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 água estagnada; pântano; lagoa, após recuo de rio ou mar 2 lago 3 lago artificial 4 mar ou braço de mar.</p></section></article>\n<article id=\"entry-dgp-25215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμνόβιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 608 na letra λ · nº geral 25215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vive nos pântanos. 〈λίμνη〉</p></section></article>\n<article id=\"entry-dgp-25216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμνουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 609 na letra λ · nº geral 25216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que trabalha nos pântanos ou lagos; pescador. 〈λίμνη, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-25217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμνώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 610 na letra λ · nº geral 25217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem o aspecto ou a natureza de um pântano; palustre ♦ τὸ λιμνῶδες 2 aspecto pantanoso de uma terra. 〈λίμνη, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-25218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιμοδωριεῖς, έων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 611 na letra λ · nº geral 25218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os Dórios famintos, i.e., obrigados a emigrar por causa da fome. 〈λιμός, ∆ωριεύς〉</p></section></article>\n<article id=\"entry-dgp-25219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμοθνής, ῆτος</h1><div class=\"entry-meta\"><span>DGP · ordem 612 na letra λ · nº geral 25219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que morre de fome. 〈λιμός, θνῄσκω〉</p></section></article>\n<article id=\"entry-dgp-25220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμοκτονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 613 na letra λ · nº geral 25220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 privar de alimento; pôr em dieta rigorosa 2 fazer morrer de fome. 〈λιμός, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-25221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 614 na letra λ · nº geral 25221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fome; penúria de alimentos; inanição 2 homem faminto.</p></section></article>\n<article id=\"entry-dgp-25222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 615 na letra λ · nº geral 25222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem fome; faminto 2 pouco provido de alimentos 3 próprio de quem morre de fome: λεπτὸς καὶ λιμώδης ὕμνος plut. sono leve e atormentado pela fome, de gansos famintos do Capitólio. 〈λιμός, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-25223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιμώσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 616 na letra λ · nº geral 25223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ώττω (fut. λιμώξομαι, aor. ἐλίμωξα, perf. desus.) sentir fome. 〈λιμός〉</p></section></article>\n<article id=\"entry-dgp-25224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 617 na letra λ · nº geral 25224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. de λῖς1.</p></section></article>\n<article id=\"entry-dgp-25225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίνεος-οῦς, έα-ῆ, εον-οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 618 na letra λ · nº geral 25225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de linho; feito de linho. 〈λίνον〉</p></section></article>\n<article id=\"entry-dgp-25226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινόδεσμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 619 na letra λ · nº geral 25226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ligado com um fio ou cordas. 〈λίνον, δεσμός〉</p></section></article>\n<article id=\"entry-dgp-25227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινόδετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 620 na letra λ · nº geral 25227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">λινόδεσμος. 〈λίνον, δέω〉</p></section></article>\n<article id=\"entry-dgp-25228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοθώρηξ, ηκος</h1><div class=\"entry-meta\"><span>DGP · ordem 621 na letra λ · nº geral 25228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de couraça de linho. 〈λί­νον, θώρηξ〉</p></section></article>\n<article id=\"entry-dgp-25229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινόκροκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 622 na letra λ · nº geral 25229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tecido de linho. 〈λίνον, κρέκω〉</p></section></article>\n<article id=\"entry-dgp-25230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 623 na letra λ · nº geral 25230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 linho, planta: λίνου σπέρμα tuc. grão de linho 2 fio de linho: prov. λίνον λίνῳ συνάπτειν plat. unir fio com fio, i.e., reunir coisas semelhantes 3 fio das Parcas; fio da vida: ὑπὲρ τὸ λίνον luc. apesar do destino 4 linha de pescar 5 rede de pescador 6 rede de caçador 7 tecido ou veste de linho 8 vela de navio.</p></section></article>\n<article id=\"entry-dgp-25231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινόπληκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 624 na letra λ · nº geral 25231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que teme a rede (animal). 〈λίνον, πλήσσω〉</p></section></article>\n<article id=\"entry-dgp-25232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοπόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 625 na letra λ · nº geral 25232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que enfuna as velas (vento). 〈λίνον, πο­ρεύομαι〉</p></section></article>\n<article id=\"entry-dgp-25233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινόπτερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 626 na letra λ · nº geral 25233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de asas, i.e., de velas de linho (nau). 〈λίνον, πτερόν〉</p></section></article>\n<article id=\"entry-dgp-25234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινορραφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 627 na letra λ · nº geral 25234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 costurado com fio de linho 2 que entrelaça as malhas de uma rede; que faz rede (pescador). 〈λίνον, ῥάπτω〉</p></section></article>\n<article id=\"entry-dgp-25235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 628 na letra λ · nº geral 25235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Lino, antigo aedo de Tebas, mestre de Orfeu 2 canto composto por ou sobre Lino 3 canto fúnebre sobre ou em honra de Lino.</p></section></article>\n<article id=\"entry-dgp-25236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοστολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 629 na letra λ · nº geral 25236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vestido de linho. 〈λίνον, στολή〉</p></section></article>\n<article id=\"entry-dgp-25237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινουργός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 630 na letra λ · nº geral 25237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que trabalha o linho; cordoeiro ou tecelão 2 espécie de pedra 3 pl. espécie de ganso. 〈λίνον, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-25238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοῦς, ῆ, οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 631 na letra λ · nº geral 25238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de λίνεος.</p></section></article>\n<article id=\"entry-dgp-25239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λινοφθόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 632 na letra λ · nº geral 25239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que destrói o linho, i.e., que rasga o tecido. 〈λίνον, φθείρω〉</p></section></article>\n<article id=\"entry-dgp-25240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίπα</h1><div class=\"entry-meta\"><span>DGP · ordem 633 na letra λ · nº geral 25240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com gordura: λίπ’ ἐλαίῳ χρῖσαι hom., λίπ’ ἀλεί­φειν hom. untar com gordura, λ. ἀλείφεσθαι hom. untar-se.</p></section></article>\n<article id=\"entry-dgp-25241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 634 na letra λ · nº geral 25241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(at. só pres. e aor. ἐλίπανα ou ἐλίπηνα; pas. só pres. e perf. λελίπασμαι) 1 untar; ungir 2 adubar; fertilizar; fecundar: λιπ. χώραν ὕδασι eur. fecundar a terra com as águas. 〈λίπος〉</p></section></article>\n<article id=\"entry-dgp-25242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιπαρεῖς, έων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 635 na letra λ · nº geral 25242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os habitantes das ilhas Lípares.</p></section></article>\n<article id=\"entry-dgp-25243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 636 na letra λ · nº geral 25243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apegar-se a; insistir; persistir em, dat. ou part.: λιπ. τῇ πόσει her. persistir em beber, ἐλιπάρεε ἱστορέων her. persistia em interrogar, continuava a interrogar 2 pedir com insistência; suplicar de modo premente, inf.: ὅσα λιπαρεῖς παρ’ ἐμοῦ μανθάνειν xen. tudo o que com tanta insistência procuras saber de mim 3 importunar; assediar: λιπαροῦντα τὰς τράπεζας καὶ τοὺς βωμούς pol. importunando as mesas e os altares ♦ pas. 4 ser requisitado com insistência: λιπαρεῖσθαι ὑπό τινος xen. ser importunado por alguém. 〈λιπαρής〉</p></section></article>\n<article id=\"entry-dgp-25244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 637 na letra λ · nº geral 25244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se apega a; perseverante; persistente em algo, gen., πρός e ac., περί e ac. ou gen. 2 insistente; obstinado em, part.: λιπαρεῖς ἦσαν δεόμενοι plut. eram obstinados no pedido 3 incessante; incansável (coisa): λιπ. προθυμία luc. zelo infatigável, λιπ. πυρετός luc. febre constante, λιπ. χείρ sóf. mão suplicante ♦ τὸ λιπαρές 4 tenacidade; perseverança. 〈λίπος〉</p></section></article>\n<article id=\"entry-dgp-25245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 638 na letra λ · nº geral 25245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de λιπαρέω.</p></section></article>\n<article id=\"entry-dgp-25246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 639 na letra λ · nº geral 25246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. λιπαρίη, ης (ἡ) persistência; constância; perseverança. 〈λιπαρής〉</p></section></article>\n<article id=\"entry-dgp-25247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρόθρονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 640 na letra λ · nº geral 25247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de trono brilhante. 〈λιπαρός, θρόνος〉</p></section></article>\n<article id=\"entry-dgp-25248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαροκρήδεμνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 641 na letra λ · nº geral 25248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de faixas brilhantes. 〈λιπαρός, κρήδεμνον〉</p></section></article>\n<article id=\"entry-dgp-25249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαροπλόκαμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 642 na letra λ · nº geral 25249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cachos ou de tranças brilhantes. 〈λιπαρός, πλόκαμος〉</p></section></article>\n<article id=\"entry-dgp-25250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 643 na letra λ · nº geral 25250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gordo; oleoso; brilhante de óleo, de gordura, de perfumes etc.: λιπαροὶ κεφαλάς hom. com os cabelos luzentes 2 de saúde física luzente; vigoroso; forte: πόδες λιπαροί hom. pés robustos, λιπαρὰ ὀσμή artt. odor penetrante 3 opulento; rico; esplêndido: λιπαρὸν γῆρας hom. velhice opulenta, λιπαρὰς θέμιστας τελέουσιν hom. pagam ricas contribuições, λιπαρὰ κρήδεμνα hom. véus brilhantes ♦ τὸ λιπαρόν 4 substância gordurosa 5 pl. comida gordurosa. 〈λίπα〉</p></section></article>\n<article id=\"entry-dgp-25251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 644 na letra λ · nº geral 25251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gordura de animal 2 secreção de vegetal 3 pl. substâncias gordurosas 4 brilho dos olhos. 〈λιπαρός〉</p></section></article>\n<article id=\"entry-dgp-25252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπαρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 645 na letra λ · nº geral 25252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com gordura 2 na abundância.</p></section></article>\n<article id=\"entry-dgp-25253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίπασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 646 na letra λ · nº geral 25253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 substância gordurosa; gordura para untar 2 ungüento; perfume 3 secreção dos olhos; lágrima. 〈λίπα〉</p></section></article>\n<article id=\"entry-dgp-25254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 647 na letra λ · nº geral 25254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres.) 1 intr. estar gordo 2 intr. estar un­tado; estar luzidio 3 tr. ungir. 〈λίπα〉</p></section></article>\n<article id=\"entry-dgp-25255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 648 na letra λ · nº geral 25255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de λείπω.</p></section></article>\n<article id=\"entry-dgp-25256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποβοτανέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 649 na letra λ · nº geral 25256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estar privado de vegetação. 〈λείπω, βό­τανη〉</p></section></article>\n<article id=\"entry-dgp-25257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπογνώμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 650 na letra λ · nº geral 25257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος cuja idade não se pode definir. 〈λείπω, γνώμη〉</p></section></article>\n<article id=\"entry-dgp-25258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπόθριξ, τριχος</h1><div class=\"entry-meta\"><span>DGP · ordem 651 na letra λ · nº geral 25258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que perdeu os cabelos; calvo. 〈λείπω, θρίξ〉</p></section></article>\n<article id=\"entry-dgp-25259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποθυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 652 na letra λ · nº geral 25259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fraqueza; desmaio; desfalecimento. 〈λείπω, θυμός〉</p></section></article>\n<article id=\"entry-dgp-25260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπόναυς, αος</h1><div class=\"entry-meta\"><span>DGP · ordem 653 na letra λ · nº geral 25260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que abandona o navio. 〈λείπω, ναῦς〉</p></section></article>\n<article id=\"entry-dgp-25261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιπονέως, ω (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 654 na letra λ · nº geral 25261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que abandona a nau; marinheiro desertor. 〈λείπω, ναῦς〉</p></section></article>\n<article id=\"entry-dgp-25262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίπος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 655 na letra λ · nº geral 25262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gordura de animal 2 líquido gorduroso; óleo 3 secreção de vegetal 4 substância úmida e brilhante, sangue.</p></section></article>\n<article id=\"entry-dgp-25263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποστρατία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 656 na letra λ · nº geral 25263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deserção militar. 〈λείπω, στρατιά〉</p></section></article>\n<article id=\"entry-dgp-25264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποστρατίου γραφή</h1><div class=\"entry-meta\"><span>DGP · ordem 657 na letra λ · nº geral 25264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crime de deserção militar.</p></section></article>\n<article id=\"entry-dgp-25265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποτακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 658 na letra λ · nº geral 25265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abandonar seu posto; desertar. 〈λείπω, τάσσω〉</p></section></article>\n<article id=\"entry-dgp-25266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποταξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 659 na letra λ · nº geral 25266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abandono de um posto; deserção.</p></section></article>\n<article id=\"entry-dgp-25267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποψυχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 660 na letra λ · nº geral 25267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perder os sentidos; desmaiar 2 perder a coragem. 〈λείπω, ψυχή〉</p></section></article>\n<article id=\"entry-dgp-25268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιποψυχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 661 na letra λ · nº geral 25268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desmaio. 〈λείπω, ψυχή〉</p></section></article>\n<article id=\"entry-dgp-25269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 662 na letra λ · nº geral 25269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 desejar intensamente, gen. ♦ part. perf. méd. λελιμμένος 2 ávido de, gen.</p></section></article>\n<article id=\"entry-dgp-25270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίς1, λιός</h1><div class=\"entry-meta\"><span>DGP · ordem 663 na letra λ · nº geral 25270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. λῖν, pl. nom. λίες, dat. poét. λίεσσιν (ὁ) leão.</p></section></article>\n<article id=\"entry-dgp-25271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίς2</h1><div class=\"entry-meta\"><span>DGP · ordem 664 na letra λ · nº geral 25271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) ép. liso; escorregadio: λὶς πέτρη hom. pedra lisa, escorregadia.</p></section></article>\n<article id=\"entry-dgp-25272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίς3</h1><div class=\"entry-meta\"><span>DGP · ordem 665 na letra λ · nº geral 25272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só dat. λιτί, ac. sing. ou pl. λῖτα (duv. τό ou ὁ) 1 tecido liso e fino de linho 2 coberta; lençol 3 capa para cobrir carro; manta para cobrir assento.</p></section></article>\n<article id=\"entry-dgp-25273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῖσαι</h1><div class=\"entry-meta\"><span>DGP · ordem 666 na letra λ · nº geral 25273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imper. aor.1 de λίσσομαι.</p></section></article>\n<article id=\"entry-dgp-25274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 667 na letra λ · nº geral 25274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de λίσσομαι.</p></section></article>\n<article id=\"entry-dgp-25275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λισσάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 668 na letra λ · nº geral 25275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 escorregadio; polido; luzidio ♦ ἡ λισσάς 2 rocha lisa, polida, luzidia. 〈λισσός〉</p></section></article>\n<article id=\"entry-dgp-25276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίσσασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 669 na letra λ · nº geral 25276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. ép. de λίσσομαι.</p></section></article>\n<article id=\"entry-dgp-25277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίσσεαι</h1><div class=\"entry-meta\"><span>DGP · ordem 670 na letra λ · nº geral 25277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. pres. ind., λίσσεο 2a sing. pres. imper., λισσέσκετο 3a sing. impf. iter., λίσσηαι 2a sing. pres. subj., poét. de λίσσομαι.</p></section></article>\n<article id=\"entry-dgp-25278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 671 na letra λ · nº geral 25278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. λίσομαι, aor. ἐλισάμην) 1 pedir com insistência; implorar; rogar; suplicar a alguém, ac., em nome de alguém, gen. ou πρό, πρός, ὑπέρ e gen.: λ. Ζηνὸς ἠδὲ θέμιστος hom. implorar por Zeus e Témis, πρός νυν θεῶν σε λίσσομαι ἐμοὶ πίθεσθαι sóf. em nome dos deuses, eu te suplico que me escutes, πρὸ κείνων καὶ τέκνων σε λίσσομαι eur. por eles e seus filhos imploro-te 2 pedir; suplicar algo, ac. ou or., a alguém, dat.: μὴ πρόλειπε, λίσσομαι, πάτερ ésql. não me abandones, meu pai, suplico-te, μὴ, λίσσομαι σ’, αὔδα τάδε sóf. não digas isto, suplico-te, λ. τινὰ μένειν hom. pedir a alguém que fique, λ. τινὰ ὅπως νημερτέα εἴπῃ hom. suplicar a alguém que diga a verdade.</p></section></article>\n<article id=\"entry-dgp-25279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λισσός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 672 na letra λ · nº geral 25279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">polido; luzidio; liso.</p></section></article>\n<article id=\"entry-dgp-25280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιστρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 673 na letra λ · nº geral 25280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cavar ao redor; abacelar uma planta. 〈λίστρον〉</p></section></article>\n<article id=\"entry-dgp-25281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίστρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 674 na letra λ · nº geral 25281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pá ou enxada.</p></section></article>\n<article id=\"entry-dgp-25282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῖτα</h1><div class=\"entry-meta\"><span>DGP · ordem 675 na letra λ · nº geral 25282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λίς3.</p></section></article>\n<article id=\"entry-dgp-25283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτανεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 676 na letra λ · nº geral 25283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">invocar com preces; rogar; suplicar algo, ac. ou inf., a alguém, ac.: πολλὰ γούνων λιτανεύειν hom. dirigir repetidas preces [a alguém], abraçando-lhe os joelhos. 〈λίτανος〉</p></section></article>\n<article id=\"entry-dgp-25284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίτανος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 677 na letra λ · nº geral 25284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suplicante ♦ τὰ λίτανα 2 preces. 〈λιτή〉</p></section></article>\n<article id=\"entry-dgp-25285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτέσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 678 na letra λ · nº geral 25285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de λίτομαι.</p></section></article>\n<article id=\"entry-dgp-25286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 679 na letra λ · nº geral 25286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. 1 prece; súplica a alguém, gen., por alguém, gen.: λιτὰς ἐπεύχεσθαι sóf., λιταῖς εὔχεσθαι ésql., λιτῇσι λίσσεσθαι hom. pedir por meio de preces, λ. δέχεσθαι sóf. acolher preces ♦ αἱ Λιταί 2 Preces, person.</p></section></article>\n<article id=\"entry-dgp-25287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτί</h1><div class=\"entry-meta\"><span>DGP · ordem 680 na letra λ · nº geral 25287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λίς3.</p></section></article>\n<article id=\"entry-dgp-25288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτοίμην</h1><div class=\"entry-meta\"><span>DGP · ordem 681 na letra λ · nº geral 25288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">opt. aor.2 de λίτομαι.</p></section></article>\n<article id=\"entry-dgp-25289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίτομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 682 na letra λ · nº geral 25289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">λίσσομαι.</p></section></article>\n<article id=\"entry-dgp-25290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 683 na letra λ · nº geral 25290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 simples; sem adornos; sem aparato: λιτὴ δίαιτα plut. alimentação frugal, λιτὸς περὶ δίαιταν plut. simples no modo de viver, κατὰ τὴν ἐσθῆτα καὶ τὴν σίτησιν ἀφελὴς καὶ λιτός pol. simples e modesto no vestir e no alimentar-se 2 pobre; mesquinho; fraco; pequeno ♦ τὸ λιτόν 3 simplicidade; frugalidade 4 simples; contido; sem elevação (estilo). 〈λίς2〉</p></section></article>\n<article id=\"entry-dgp-25291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιτότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 684 na letra λ · nº geral 25291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 simplicidade; ausência de adornos 2 Ret. litote. 〈λιτός〉</p></section></article>\n<article id=\"entry-dgp-25292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίτρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 685 na letra λ · nº geral 25292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 libra romana (= 327 g) 2 moeda de prata da Sicília, de baixo valor.</p></section></article>\n<article id=\"entry-dgp-25293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 686 na letra λ · nº geral 25293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ant. át. = νίτρον.</p></section></article>\n<article id=\"entry-dgp-25294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίτυον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 687 na letra λ · nº geral 25294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bastão dos adivinhos romanos. [lat.]</p></section></article>\n<article id=\"entry-dgp-25295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιχανός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 688 na letra λ · nº geral 25295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o dedo indicador.</p></section></article>\n<article id=\"entry-dgp-25296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίχανος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 689 na letra λ · nº geral 25296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corda da lira tocada com o indicador da mão esquerda 2 o som desta corda.</p></section></article>\n<article id=\"entry-dgp-25297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίχας,</h1><div class=\"entry-meta\"><span>DGP · ordem 690 na letra λ · nº geral 25297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. Λίχης, ου e α (ὁ) Licas, servidor de Héracles.</p></section></article>\n<article id=\"entry-dgp-25298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίχης</h1><div class=\"entry-meta\"><span>DGP · ordem 691 na letra λ · nº geral 25298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Λίχας.</p></section></article>\n<article id=\"entry-dgp-25299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιχμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 692 na letra λ · nº geral 25299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vibrar a língua 2 lamber.</p></section></article>\n<article id=\"entry-dgp-25300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιχμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 693 na letra λ · nº geral 25300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor.) at. e méd. = λιχμάζω.</p></section></article>\n";
